144	    @Test
145	    @DisplayName("同一预占并发确认/取消：只允许一个终态，额度不重复释放、不变负")
146	    void concurrentConfirmAndCancel_singleTerminal_noDoubleRelease() throws Exception {
147	        service.createCampaign(new CreateCampaignRequest("req-c", "cap", 1, 1));
148	        ReservationResponse r = service.apply(new ApplyExposureRequest("req-a", "cap", "v1"));
149	
150	        int threads = 24;
