        @Test
        @DisplayName("跨零点 22:00-06:00：22:00 至午夜、午夜后至 06:00 前在内，06:00 起在外")
        void crossMidnightWindow() {
            assertTrue(QuietHoursCalculator.isWithinQuietHours(1320, 1320, 360));
