                // 并发事务抢先插入（可能尚未提交），进入下一轮：其提交则 UPDATE 命中，回滚则 INSERT 成功
            }
        }
        throw new IllegalStateException("failed to increment suppression counter after retries: "
                + campaignId + "/" + visitorId + "/" + utcDate);
    }
