void quietHoursDoNotAffectExistingReservations() {
    createCampaign("req-c", "cm", 1, 1, CampaignCategory.MARKETING);
    // 初始无静默，申请成功
    ApplyResponse r = service.apply(new ApplyExposureRequest("req-a1", "cm", "v1"));
