    register("req-q1", "v1", 0, 0, 1439, false);
    var confirmed = service.confirm(reservationId, new ReservationActionRequest("req-k1"));
    assertEquals("CONFIRMED", confirmed.status().name());

    // 取消路径：另一预占在登记静默后仍可取消并释放
    ApplyResponse r2Unblocked = update("req-q2", "v1", 0, 1200, 1300, false, 1);
    assertEquals(2, r2Unblocked.version());
    // 当前 10:00 UTC 不在 20:00-21:40 静默区间，可再申请（上一预占已确认占用唯一总额度，
    // 故改用新公告）
    createCampaign("req-c2", "cm2", 1, 1, CampaignCategory.SERVICE);
    ApplyResponse r2 = service.apply(new ApplyExposureRequest("req-a2", "cm2", "v1"));
    assertEquals("RESERVED", r2.outcome().name());
    register("req-q3", "v2", 0, 0, 1439, false);
    var cancelled = service.cancel(r2.reservationId(), new ReservationActionRequest("req-x1"));
    assertEquals("CANCELLED", cancelled.status().name());
    assertEquals(0, service.queryQuota("cm2", "v1", LocalDate.of(2026, 9, 22)).usedTotal());
}

